      const j = v9jac(v9bigrams(v9toks("user name is sara")), v9bigrams(v9toks("user name is sara johnson")));
      T("jaccard: partial similarity band", j > 0.4 && j < 0.9, j.toFixed(3));
      const e1 = applyEdits("function add(a, b) {\n  return a + b;\n}\n", { old_string: "return a + b;", new_string: "return Number(a) + Number(b);" });
      T("edit: unique replace ok", e1.content && e1.content.includes("Number(a)"), JSON.stringify(e1).slice(0, 120));
