async function handleUiLabel(env, msg, text, admin) {
  const t = text.trim();
  const label = t.replace(/^[^\p{L}\p{N}]+/u, "").trim();
  const map = {
    "\u062A\u0633\u06A9\u200C\u0647\u0627": "/tasks",
    "Tasks": "/tasks",
    "\u062D\u0627\u0641\u0638\u0647": "/memory",
    "Memory": "/memory",
    "\u0627\u0633\u06A9\u06CC\u0644\u200C\u0647\u0627": "/skills",
    "Skills": "/skills",
    "\u062F\u0631\u0628\u0627\u0631\u0647": "/about",
    "About": "/about",
    "\u0631\u0627\u0647\u0646\u0645\u0627": "/help",
    "Help": "/help"
  };
  const target = map[label];
  if (!target) return false;
  await handleCommand(env, msg, target, admin);
  return true;
}
async function mainKeyboard(env, fa) {
  const btn = async (t, slot, style) => {
    const b = await slotBtn(env, t, slot, "kb:none", style);
    delete b.callback_data;
    return b;
  };
  return {
    keyboard: [
      [await btn(fa ? "\u062A\u0633\u06A9\u200C\u0647\u0627" : "Tasks", "keyboard.tasks"), await btn(fa ? "\u062D\u0627\u0641\u0638\u0647" : "Memory", "keyboard.memory")],
      [await btn(fa ? "\u0627\u0633\u06A9\u06CC\u0644\u200C\u0647\u0627" : "Skills", "keyboard.skills"), await btn(fa ? "\u062F\u0631\u0628\u0627\u0631\u0647" : "About", "keyboard.about", "primary")],
      [await btn(fa ? "\u0631\u0627\u0647\u0646\u0645\u0627" : "Help", "keyboard.help")]
    ],
    is_persistent: true,
    resize_keyboard: true,
    input_field_placeholder: fa ? "\u0628\u0631\u0627\u06CC \u0645\u0646 \u0628\u0646\u0648\u06CC\u0633\u2026" : "Write to me\u2026"
  };
}
