async function viewStats(env) {
  const cfg = await getConfig(env);
  const today0 = now() - 86400;
  const msgsToday = await count(env, "SELECT COUNT(*) c FROM messages WHERE ts > ?", today0);
  const banned = await count(env, "SELECT COUNT(*) c FROM users WHERE status='banned'");
  const done = await count(env, "SELECT COUNT(*) c FROM tasks WHERE status='done'");
  const failed = await count(env, "SELECT COUNT(*) c FROM tasks WHERE status IN ('failed','cancelled')");
  const errors = await count(env, "SELECT COUNT(*) c FROM events WHERE type LIKE '%error%'");
  const emojis = await count(env, "SELECT COUNT(*) c FROM emoji_lib");
  const runs = await count(env, "SELECT COUNT(*) c FROM events WHERE type='agent_run'");
  const text = `\u{1F4CA} <b>\u0622\u0645\u0627\u0631 \u0632\u0646\u062F\u0647</b>

\u2022 \u067E\u06CC\u0627\u0645 \u06F2\u06F4 \u0633\u0627\u0639\u062A \u0627\u062E\u06CC\u0631: <b>${msgsToday}</b>
\u2022 \u0627\u062C\u0631\u0627\u06CC \u0627\u06CC\u062C\u0646\u062A: <b>${runs}</b>
\u2022 \u062A\u0633\u06A9 \u0627\u0646\u062C\u0627\u0645\u200C\u0634\u062F\u0647: <b>${done}</b> \u2022 \u0646\u0627\u0645\u0648\u0641\u0642: <b>${failed}</b>
\u2022 \u062E\u0637\u0627\u0647\u0627: <b>${errors}</b>
\u2022 \u06A9\u0627\u0631\u0628\u0631 \u0645\u0633\u062F\u0648\u062F: <b>${banned}</b>
\u2022 \u0627\u06CC\u0645\u0648\u062C\u06CC \u067E\u0631\u0645\u06CC\u0648\u0645 \u0622\u0645\u0648\u062E\u062A\u0647\u200C\u0634\u062F\u0647: <b>${emojis}</b>

\u{1F9E0} \u0645\u062F\u0644: <code>${escHtml(cfg.agent.model)}</code>
\u{1F4AC} \u067E\u0627\u0633\u062E: <code>${cfg.agent.reply_mode}</code> \u2022 \u0627\u0633\u062A\u0631\u06CC\u0645: <code>${cfg.agent.stream ? "\u0631\u0648\u0634\u0646" : "\u062E\u0627\u0645\u0648\u0634"}</code>`;
  return {
    text,
    kb: [[await pbtn(env, "\u0628\u0627\u0632\u06AF\u0634\u062A", "panel.back", "a:home", "primary")]]
  };
}
async function viewUsers(env, page) {
  const per = 8;
  const total = await count(env, "SELECT COUNT(*) c FROM users");
  const pages = Math.max(1, Math.ceil(total / per));
  const p = Math.min(Math.max(0, page), pages - 1);
  const r = await env.DB.prepare("SELECT * FROM users ORDER BY last_seen DESC LIMIT ? OFFSET ?").bind(per, p * per).all();
  const rows2 = r.results || [];
  const lines = rows2.map((u) => {
    const mark = u.status === "banned" ? "\u26D4\uFE0F" : "\u2705";
    return `${mark} <b>${escHtml(fullName(u))}</b> ${u.username ? `@${escHtml(u.username)}` : ""} <code>${u.user_id}</code> \u2014 ${u.msg_count} \u067E\u06CC\u0627\u0645`;
  });
  const text = `\u{1F465} <b>\u06A9\u0627\u0631\u0628\u0631\u0627\u0646</b> (\u0635\u0641\u062D\u0647 ${p + 1}/${pages})

${lines.join("\n") || "\u2014"}`;
  const kb = [];
  for (const u of rows2) {
    kb.push([{ text: `\u{1F464} ${escHtml(fullName(u)).slice(0, 24)} \u2014 ${u.user_id}`, callback_data: `a:user:${u.user_id}` }]);
  }
  const nav = [];
  if (p > 0) nav.push({ text: "\u23EA", callback_data: `a:users:p${p - 1}` });
  if (p < pages - 1) nav.push({ text: "\u23E9", callback_data: `a:users:p${p + 1}` });
  kb.push(nav, [await pbtn(env, "\u0628\u0627\u0632\u06AF\u0634\u062A", "panel.back", "a:home", "primary")]);
  return { text, kb };
}
async function viewUser(env, userId) {
  const u = await env.DB.prepare("SELECT * FROM users WHERE user_id = ?").bind(userId).first();
  if (!u) return { text: "\u06A9\u0627\u0631\u0628\u0631 \u06CC\u0627\u0641\u062A \u0646\u0634\u062F.", kb: [[await pbtn(env, "\u0628\u0627\u0632\u06AF\u0634\u062A", "panel.back", "a:users:p0", "primary")]] };
  const banned = u.status === "banned";
  const text = `\u{1F464} <b>${escHtml(fullName(u))}</b>

\u2022 \u0622\u06CC\u062F\u06CC: <code>${u.user_id}</code>
\u2022 \u06CC\u0648\u0632\u0631\u0646\u06CC\u0645: ${u.username ? `@${escHtml(u.username)}` : "\u2014"}
\u2022 \u0632\u0628\u0627\u0646: <code>${u.language_code || "\u2014"}</code> \u2022 \u067E\u0631\u0645\u06CC\u0648\u0645: ${u.is_premium ? "\u2705" : "\u2014"}
\u2022 \u0627\u0648\u0644\u06CC\u0646 \u067E\u06CC\u0627\u0645: <code>${new Date(u.first_seen * 1e3).toISOString().slice(0, 16).replace("T", " ")}</code>
\u2022 \u062A\u0639\u062F\u0627\u062F \u067E\u06CC\u0627\u0645: <b>${u.msg_count}</b>
\u2022 \u0648\u0636\u0639\u06CC\u062A: ${banned ? "\u26D4\uFE0F \u0645\u0633\u062F\u0648\u062F" : "\u2705 \u0641\u0639\u0627\u0644"}`;
  const kb = [
    banned ? [{ text: "\u2705 \u0631\u0641\u0639 \u0645\u0633\u062F\u0648\u062F\u06CC", callback_data: `a:unban:${userId}`, style: "success" }] : [{ text: "\u26D4\uFE0F \u0645\u0633\u062F\u0648\u062F\u0633\u0627\u0632\u06CC", callback_data: `a:ban:${userId}`, style: "danger" }],
    [await pbtn(env, "\u0628\u0627\u0632\u06AF\u0634\u062A", "panel.back", "a:users:p0", "primary")]
  ];
  return { text, kb };
}
