      [{ text: `\u06AF\u0631\u0648\u0647: ${cfg.group_mode === "mentions" ? "\u0645\u0646\u0634\u0646" : cfg.group_mode === "always" ? "\u0647\u0645\u0647" : "\u062E\u0627\u0645\u0648\u0634"}`, callback_data: "a:cycle:group_mode" }],
      [await pbtn(env, "\u0633\u0647\u0645\u06CC\u0647 \u067E\u06CC\u0627\u0645", "x.msgs_per_hour", "a:edit:msgs_per_hour", void 0, "\u23F3"), await pbtn(env, "\u0628\u0648\u062F\u062C\u0647 \u0627\u0628\u0632\u0627\u0631", "x.tool_budget", "a:edit:tool_budget", void 0, "\u{1F9EE}")],
      [await pbtn(env, "\u0628\u0627\u0632\u06AF\u0634\u062A", "panel.back", "a:home", "primary")]
