        if (!stallWarned && Date.now() - state.lastPollOk > 3e5) {
          stallWarned = true;
          console.warn("[portable] polling stalled > 5min \u2014 \u0634\u0628\u06A9\u0647 \u06CC\u0627 \u062A\u0644\u06AF\u0631\u0627\u0645 \u0642\u0637\u0639 \u0627\u0633\u062A\u061B \u062A\u0644\u0627\u0634 \u0627\u062F\u0627\u0645\u0647 \u062F\u0627\u0631\u062F");
        }
