var shutdownHooks = [];
function onShutdown(fn) {
  shutdownHooks.push(fn);
}
function installSingleInstance(dbPath) {
  try {
    const lockPath = import_node_path.default.join(import_node_path.default.dirname(dbPath), ".instance.lock");
    if (import_node_fs.default.existsSync(lockPath)) {
      let skip = false;
      try {
        const prev = JSON.parse(import_node_fs.default.readFileSync(lockPath, "utf8") || "{}");
        const pid = Number(prev && prev.pid);
        if (Number.isInteger(pid) && pid > 0) {
          let alive = false;
          try {
            process.kill(pid, 0);
            alive = true;
          } catch (e) {
            alive = e.code === "EPERM";
          }
          const stale = import_node_fs.default.statSync(lockPath).mtimeMs < Date.now() - 24 * 36e5;
          if (alive && !stale) skip = true;
        }
      } catch {
      }
      if (skip) {
        console.log("[portable] another instance is still alive \u2014 this run exits (overlap guard; state is safe)");
        process.exit(0);
      }
    }
    import_node_fs.default.mkdirSync(import_node_path.default.dirname(lockPath), { recursive: true });
    import_node_fs.default.writeFileSync(lockPath, JSON.stringify({ pid: process.pid, at: Date.now() }));
    process.on("exit", () => {
      try {
        import_node_fs.default.unlinkSync(lockPath);
      } catch {
      }
    });
  } catch (e) {
    console.warn("[portable] single-instance guard unavailable:", e && e.message);
  }
}
function installMaxLife(ms) {
  const t = Number(ms);
  if (!Number.isFinite(t) || t < 5e3) return;
  setTimeout(() => {
    console.log(`[portable] max-life ${Math.round(t / 1e3)}s reached \u2014 clean exit (cron cadence; everything is persisted)`);
    process.exit(0);
  }, t);
}
function graceful(signal) {
  console.log(`
[portable] ${signal} received \u2014 shutting down cleanly (state is already persisted)`);
  for (const fn of shutdownHooks) {
    try {
      fn();
    } catch {
    }
  }
  process.exit(0);
}
process.on("SIGINT", () => graceful("SIGINT"));
process.on("SIGTERM", () => graceful("SIGTERM"));

